from pathlib import Path

master=Path('00-READ-FIRST-EGE-DEMOVERSII-MASTER.md')
s=master.read_text(encoding='utf-8')
reg='RUSSKIY-EGE-DEMOVERSII-REGLAMENT-SOCHINENIYA-I-PROVERKI.md'
if reg not in s:
    anchor='''Для математики дополнительно обязателен:\n\n`MATEMATIKA-EGE-DEMOVERSII-REGLAMENT-SOZDANIYA-I-PROVERKI.md`\n'''
    insert=anchor+'''\nДля русского языка дополнительно обязателен:\n\n`RUSSKIY-EGE-DEMOVERSII-REGLAMENT-SOCHINENIYA-I-PROVERKI.md`\n\nОн фиксирует постоянную архитектуру сочинения, post-exam проверки, multipage scan/zoom, student-facing UX, state/reset/privacy и отображаемого общего результата. Цифры, критерии, пороги и официальные основания каждого года при этом заново сверяются по источникам конкретного года.\n'''
    if anchor not in s: raise SystemExit('master anchor missing')
    s=s.replace(anchor,insert,1)
    master.write_text(s,encoding='utf-8')

mods=Path('demo-production-standard/SUBJECT-FEATURE-MODULES.md')
s=mods.read_text(encoding='utf-8')
start=s.index('## 8. Длинный текст, сочинение, изложение')
end=s.index('\n---\n\n## 9.',start)
section='''## 8. Длинный текст, сочинение, изложение\n\nПодключить, если есть развёрнутый текст с ручной/экспертной оценкой. Для ЕГЭ по русскому языку дополнительно обязателен предметный регламент `RUSSKIY-EGE-DEMOVERSII-REGLAMENT-SOCHINENIYA-I-PROVERKI.md`.\n\nОбязательно:\n\n- технический счётчик слов помечен как ориентировочный;\n- официальные пороги, основания нуля, шкалы и каскады критериев берутся только из документов конкретного года;\n- неавтоматизируемые основания не вычисляются эвристикой;\n- автосохранение защищено;\n- экзаменационный ввод не получает browser spellcheck/autocorrect/writing suggestions, если это даёт подсказку ученику;\n- после finish текст, введённый в экзаменационном режиме, фиксируется read-only;\n- для бумажного режима после finish допускается ручной перенос текста;\n- если используются фото/сканы, поддерживаются несколько страниц и удобный zoom; нельзя обещать persistence файлов, если его нет;\n- автоматическая проверка развёрнутого ответа не маскируется под экспертную;\n- проверка после экзамена запускается явным действием пользователя, если во время набора она не должна давать подсказки;\n- набор/редактирование до явного запуска не создаёт findings и не меняет критерии;\n- редактирование после проверки инвалидирует зависящие от текста результаты и требует повторной проверки;\n- контекстно-зависимые эвристики остаются advisory и не создают жёсткий score cap без отдельной однозначной validation path;\n- отсутствие найденных мест не означает отсутствия ошибок и не даёт автоматический максимум;\n- непустые error/advisory состояния визуально различимы, пустые состояния нейтральны;\n- у критериев есть понятные student-facing подсказки, построенные по критериям конкретного года;\n- после полной ручной/учебной оценки развёрнутой части можно показать общий учебный результат как сумму автоматической части и оценки пользователя, с явной маркировкой происхождения второй части;\n- если текст отправляется во внешний сервис проверки, это раскрывается пользователю; файлы/сканы не отправляются без отдельной необходимости и раскрытия;\n- внешний check-state привязан к текущей попытке и не наследуется новой попыткой;\n- новая попытка очищает отдельный review/check state, а reload текущей running/finished попытки сохраняет его.\n\nBrowser/unit gate обязательно покрывает: отсутствие анализа при наборе, явный запуск, повторную проверку после редактирования, новую попытку без stale state, multipage upload/zoom, критерийные зависимости, zero gates, общий displayed result, mobile widths и console errors.\n'''
s=s[:start]+section+s[end:]
mods.write_text(s,encoding='utf-8')

